// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.rule.annotationsimport com.roshan.persona.brain.rule.BrainRuleimport dagger.Bindsimport dagger.Moduleimport dagger.hilt.InstallInimport dagger.hilt.components.SingletonComponentimport dagger.multibindings.IntoSetimport javax.inject.Qualifierimport kotlin.reflect.KClass/** * NOUS — Rule annotations for declarative rule registration. * * Rules annotated with [Rule] are auto-discovered and registered in * [com.roshan.persona.brain.rule.registry.RuleRegistry] via Hilt multibinding. * * Usage: * ```kotlin * @Singleton * class TorchOnRule @Inject constructor() : BrainRule { *     override val id = "torch_on_rule" *     override val priority = 10 *     override val condition = RuleCondition.IntentIs(Intent.TorchOn::class) *     override val action = RuleAction.SystemCall(SystemOperation.SetTorch(true)) *     override val tags = setOf("system", "torch") * } * * @Module * @InstallIn(SingletonComponent::class) * abstract class TorchRulesModule { *     @Binds @IntoSet *     abstract fun bindTorchOnRule(impl: TorchOnRule): BrainRule * } * ``` * * Note: For Module 2, we use explicit Hilt modules instead of KSP codegen * for simplicity. KSP codegen can be added later (Module 8+) to auto-generate * the Hilt module from @Rule-annotated classes. *//** * Marks a class as a brain rule with metadata. * * @property priority Lower = higher priority (default 100 = standard) * @property tags Grouping tags for organization */@Qualifier@Retention(AnnotationRetention.RUNTIME)@Target(AnnotationTarget.CLASS)annotation class Rule(    val priority: Int = 100,    val tags: Array<String> = [],)/** * Marks a Hilt module that contributes rules to the multibinding. */@Qualifier@Retention(AnnotationRetention.RUNTIME)@Target(AnnotationTarget.CLASS)annotation class RulesModule/** * Built-in rules module — registers all built-in rules. * * Feature modules can contribute their own [RulesModule]-annotated modules * to add rules without modifying the brain module. */@Module@InstallIn(SingletonComponent::class)abstract class BuiltInRulesModule {    // Built-in rules are registered here as the project grows.    // Module 2 ships with a minimal set (torch rules) for testing.    // Real rules (volume, brightness, mute, etc.) ship in Step 2.3.}